def solve(inputs: dict) -> float:
    M = inputs.get('M', inputs.get('matrix'))
    n = inputs.get('power', inputs.get('exponent', inputs.get('n')))
    mod = inputs.get('mod', inputs.get('modulus'))
    if M is None:
        M = [[inputs['a'], inputs['b']], [inputs['c'], inputs['d']]]
    M = [[int(M[0][0]) % mod, int(M[0][1]) % mod],
         [int(M[1][0]) % mod, int(M[1][1]) % mod]]
    R = [[1, 0], [0, 1]]
    def mul(A, B):
        return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % mod,
                 (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % mod],
                [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % mod,
                 (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % mod]]
    while n:
        if n & 1:
            R = mul(R, M)
        M = mul(M, M)
        n >>= 1
    return sum(map(sum, R))

